"use client";

import * as React from "react";

type AvatarProps = {
  src?: string | null;
  name?: string | null;
  size?: number; // px
  className?: string;
  rounded?: "full" | "md";
};

function getInitials(name?: string | null): string {
  if (!name) return "";
  const parts = name
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (parts.length === 0) return "";
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase();
  return (parts[0]![0] + parts[parts.length - 1]![0]).toUpperCase();
}

// Deterministic pastel background from name
function colorFromString(str?: string | null) {
  const s = (str ?? "?").toString();
  let hash = 0;
  for (let i = 0; i < s.length; i++) hash = (hash << 5) - hash + s.charCodeAt(i);
  const hue = Math.abs(hash) % 360;
  return {
    bg: `hsl(${hue} 70% 92%)`,
    border: `hsl(${hue} 60% 80%)`,
    text: `hsl(${hue} 45% 35%)`,
  } as const;
}

export function Avatar({ src, name, size = 36, className = "", rounded = "full" }: AvatarProps) {
  const [errored, setErrored] = React.useState(false);
  const initials = getInitials(name);
  const { bg, border, text } = colorFromString(name ?? src ?? "");
  const radius = rounded === "full" ? "rounded-full" : "rounded-md";

  if (src && !errored) {
    return (
      <img
        src={src}
        alt={name ?? "Avatar"}
        width={size}
        height={size}
        onError={() => setErrored(true)}
        className={["object-cover", radius, "border border-border", className].join(" ")}
        style={{ width: size, height: size, backgroundColor: bg }}
      />
    );
  }

  return (
    <div
      role="img"
      aria-label={name ? `${name} avatar` : "Avatar"}
      className={["grid place-items-center select-none", radius, className].join(" ")}
      style={{ width: size, height: size, backgroundColor: bg, border: `1px solid ${border}`, color: text }}
    >
      <span className="font-semibold" style={{ fontSize: Math.max(10, Math.round(size * 0.4)) }}>
        {initials || "?"}
      </span>
    </div>
  );
}

export default Avatar;
